/**
 * Inline styling for web-native text payloads.
 *
 * A payload's HTML is injected into a renderer-owned `<div>` inside a
 * `<foreignObject>` (see `renderer/native/elements.ts`).  That div inherits
 * whatever the *host page* sets on `body`/`html` — font, weight, letter
 * spacing, white-space, font features … — which would silently change text and
 * math metrics and break the pitch measured at construction time.
 *
 * The fix is to pin every property that can change advances into a wrapper
 * element that the payload owns.  The wrapper is a block that fills the box and
 * left-aligns its content, so glyphs sit on their own bearings instead of being
 * centred in the measured advance by the renderer's `text-align: center`.
 *
 * The measurement probes (see `native_text.ts` and `katex.ts`) apply exactly
 * the same declarations through {@link applyPinnedTextStyle}, so the measured
 * advance and the rendered glyph cannot drift apart.
 */
/**
 * wanim's default CSS font stack for DOM text.
 *
 * DejaVu Sans is first because it is the font the Node/pango path pins by
 * default; the remaining entries are generic substitutes for hosts that do not
 * ship it, and the final `sans-serif` guarantees a generic family.
 *
 * Family names are single-quoted: the stack is embedded in a double-quoted
 * `style="..."` attribute, so double quotes would terminate the attribute.
 */
export declare const DEFAULT_DOM_FONT_FAMILY = "'DejaVu Sans', 'Noto Sans', 'Liberation Sans', Arial, Helvetica, sans-serif";
/**
 * Layout scale of a payload's inner `<div>` (see the native renderer).
 *
 * The renderer sizes the payload box in world units but authors its content in
 * a `NATIVE_CONTENT_LAYOUT_SCALE`-times larger CSS box and scales it back with
 * `transform: scale(1 / NATIVE_CONTENT_LAYOUT_SCALE)`.  That keeps font sizes
 * in a range browsers do not clamp, and it means a measurement probe and the
 * payload render at the *same* CSS font size only when the probe scales its
 * font size by the same factor — which is why the constant lives here, next to
 * the style that both sides must agree on.
 */
export declare const NATIVE_CONTENT_LAYOUT_SCALE = 1000;
/**
 * Resolve a user-supplied font name to a CSS `font-family` value.
 *
 * An empty/absent name yields {@link DEFAULT_DOM_FONT_FAMILY}; a named family is
 * quoted when needed and always followed by a generic fallback so an unknown
 * family cannot fall through to the host page's font.
 */
export declare function cssFontFamily(font: string | null | undefined): string;
/** Options for the pinned text style shared by payloads and probes. */
export interface PinnedTextStyleOptions {
    /** Resolved CSS font stack; defaults to {@link DEFAULT_DOM_FONT_FAMILY}. */
    fontFamily?: string;
    /** Base `font-weight`; defaults to `normal`. */
    fontWeight?: string;
    /** Base `font-style`; defaults to `normal`. */
    fontStyle?: string;
    /** `line-height` (unitless); defaults to `1.2`. */
    lineHeight?: number;
    /** `white-space`; `pre` for text runs, `nowrap` for KaTeX. */
    whiteSpace?: string;
}
/**
 * Every declaration that pins the text style against the host page.
 *
 * Kept as a list (rather than two hand-written copies) so the measurement probe
 * and the rendered payload can never diverge.
 */
export declare function pinnedTextDeclarations(options?: PinnedTextStyleOptions): string[];
/** Apply {@link pinnedTextDeclarations} to a live element's style. */
export declare function applyPinnedTextStyle(target: CSSStyleDeclaration, options?: PinnedTextStyleOptions): void;
/**
 * Wrap payload HTML in an element that pins every inheritable property.
 *
 * Returned as a string because the payload travels through
 * {@link NativeTextPayload.html}.
 */
export declare function wrapPayloadHtml(innerHtml: string, options?: PinnedTextStyleOptions): string;
/** Stable CSS number formatting (no long float tails). */
export declare function formatCssNumber(value: number): string;
/**
 * Ink bounding box of an element's laid-out content, in viewport coordinates.
 *
 * Two primitives are unioned, because neither one alone sees the whole picture:
 *
 *  - a `Range` over the contents gives the laid-out *glyph* boxes of the text
 *    fragments, which is what a plain text run paints;
 *  - each descendant's own border box gives the position the element is
 *    actually painted at.  A `Range` reports the *layout* position of
 *    relatively positioned content, so it silently misses KaTeX's fraction
 *    numerators and denominators, which a `vlist` pushes outside the line box
 *    with `position: relative` — the exact overflow a `<foreignObject>` then
 *    clips.  Element boxes include that offset.
 *
 * Zero-area rects are dropped, which is what keeps KaTeX's zero-width struts
 * (three em tall) from blowing the box up.  Returns `null` when nothing
 * measurable is laid out (no layout engine, or content without text nodes).
 *
 * Measurement probes and payload boxes both go through this helper, which is
 * what makes "the box equals what the browser renders" checkable rather than
 * assumed.
 */
export declare function elementInkBounds(root: Element): {
    top: number;
    left: number;
    right: number;
    bottom: number;
} | null;
